INSERT INTO t_permission (id, permission_name, permission_code, resource_type, parent_id, sort_order, status)
VALUES (#{id}, #{permissionName}, #{permissionCode}, #{resourceType}, #{parentId}, #{sortOrder}, #{status})
ON DUPLICATE KEY UPDATE permission_name = #{permissionName}

mapper.update:
UPDATE t_permission
permission_name = #{permissionName}, sort_order = #{sortOrder}, status = #{status}, version = version + 1
WHERE id = #{id} AND deleted = 0 AND version = #{version}
